-- Fact: camera people-count events (Module 2 -> BigQuery).
--
-- `event_id` is generated by the camera, not by us. That is deliberate: a hash
-- of the payload would collapse two genuinely distinct readings that happen to
-- look identical, which inflates visits downward and conversion upward with no
-- error. The unique index in the edge SQLite buffer is the real duplicate gate;
-- here the view is the second line of defence.
--
-- `interval_seconds` is REQUIRED. "12 people" is not a measurement without it:
-- SUM(people_count) over readings of different durations is not comparable, and
-- `cameraSeconds` in the queries is only auditable because every row says how
-- long it covers. `business_date` is derived at ingest in Asia/Makassar, not by
-- BigQuery, so the rule is visible and testable.

CREATE TABLE IF NOT EXISTS finns_hospitality.fact_camera_events (
  event_id         STRING    NOT NULL,
  location_id      STRING    NOT NULL,
  business_date    DATE      NOT NULL,
  camera_id        STRING,
  observed_at      TIMESTAMP NOT NULL,
  received_at      TIMESTAMP NOT NULL,
  people_count     INT64     NOT NULL,
  interval_seconds INT64     NOT NULL,
  PRIMARY KEY (event_id) NOT ENFORCED
)
PARTITION BY business_date
CLUSTER BY location_id
OPTIONS (
  description = "At-least-once loaded camera readings; read via vw_fact_camera_events.",
  require_partition_filter = FALSE
);
